<script setup lang="ts">import { ref } from 'vue';import { storeToRefs } from 'pinia';import { useSessionStore } from '../stores/session';import { useConversationStore } from '../stores/conversation';import { streamAnswer } from '../services/chat';import type { ChatMessage } from '../types/api';const input=ref('');const controller=ref<AbortController>();const session=useSessionStore();const conversation=useConversationStore();const {messages,isStreaming}=storeToRefs(conversation);async function send(){const question=input.value.trim();if(!question||isStreaming.value)return;input.value='';messages.value.push({id:crypto.randomUUID(),role:'user',content:question});const answer: ChatMessage={id:crypto.randomUUID(),role:'assistant',content:'',citations:[],isStreaming:true};messages.value.push(answer);isStreaming.value=true;controller.value=new AbortController();try{await streamAnswer(question,session.model,conversation.cursor,controller.value.signal,{onToken:t=>answer.content+=t,onCitation:c=>answer.citations?.push(c),onDone:c=>{conversation.cursor=c;answer.isStreaming=false},onError:m=>answer.content+=`\n\n错误：${m}`})}catch(error){if((error as Error).name!=='AbortError')answer.content+='\n\n连接中断，请重试。'}finally{answer.isStreaming=false;isStreaming.value=false}}function stop(){controller.value?.abort()};</script>
<template><section class="chat"><header class="page-head"><h1 class="page-title">知识问答</h1><el-select v-model="session.model" style="width:150px"><el-option label="默认模型" value="default"/><el-option label="快速模型" value="fast"/></el-select></header><el-empty v-if="!messages.length" description="输入一个问题开始对话"/><article v-for="message in messages" :key="message.id" style="margin:20px 0"><b>{{message.role==='user'?'你':'iKnow'}}</b><p class="answer">{{message.content}}</p><el-button v-for="citation in message.citations" :key="citation.id" text type="primary" @click="$router.push(`/knowledge/${citation.id}`)">[{{citation.title}}]</el-button><div v-if="message.role==='assistant'&&!message.isStreaming"><el-button size="small" text>有帮助</el-button><el-button size="small" text>需改进</el-button></div></article><el-input v-model="input" type="textarea" :rows="3" placeholder="请输入问题，Enter 发送" @keydown.enter.exact.prevent="send"/><div style="margin-top:10px"><el-button type="primary" :loading="isStreaming" @click="send">发送</el-button><el-button v-if="isStreaming" @click="stop">停止生成</el-button></div></section></template>
